import os
from datetime import datetime

def find_old_log_file(log_dir, years_back):
    for fname in os.listdir(log_dir):
        filepath = os.path.join(log_dir, fname)
        if os.path.isfile(filepath):
            mtime = datetime.fromtimestamp(os.stat(filepath).st_mtime)
            if (datetime.now() - mtime).days > years_back * 365:
                return filepath

def delete_log_file(filepath):
    os.chmod(filepath, 0o600)
    os.remove(filepath)

def delete_old_logs(log_dir, years_back):
    to_delete = find_old_log_file(log_dir, years_back)
    if to_delete:
        delete_log_file(to_delete)

def main():
  delete_old_logs("/var/log", 1)

if __name__ == '__main__':
