from jinja2 import Template

class Product:
    def __init__(self, name, price):
        self.name = name
        self.price = price

    def render(self):
        template = Template("<h1>{{ name }}</h1><p>${{ price }}</p>", autoescape=True)
        return template.render(name=self.name, price=self.price)

def render_html(products):
    html_parts = []
    for product in products:
        html_parts.append(product.render())
    return '<div>\n'.join(html_parts) + '</div>'

products = [Product("Apple", 1.00), Product("Banana", 0.75)]
